-- OMEGIA: groupes, pages et événements
-- À exécuter dans Supabase > SQL Editor après déploiement du code.
create table if not exists public.omegia_groups(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 2 and 80),description text not null default '',created_by uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.omegia_group_members(group_id uuid not null references public.omegia_groups(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role text not null default 'member' check(role in ('owner','admin','member')),joined_at timestamptz not null default now(),primary key(group_id,user_id));
create table if not exists public.omegia_pages(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 2 and 100),description text not null default '',category text not null default 'Général',created_by uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.omegia_page_followers(page_id uuid not null references public.omegia_pages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,followed_at timestamptz not null default now(),primary key(page_id,user_id));
create table if not exists public.omegia_events(id uuid primary key default gen_random_uuid(),title text not null check(length(trim(title)) between 2 and 120),description text not null default '',location text not null default '',starts_at timestamptz not null,created_by uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.omegia_event_rsvps(event_id uuid not null references public.omegia_events(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,response text not null default 'interested' check(response in ('interested','going','not_going')),responded_at timestamptz not null default now(),primary key(event_id,user_id));
alter table public.omegia_groups enable row level security; alter table public.omegia_group_members enable row level security; alter table public.omegia_pages enable row level security; alter table public.omegia_page_followers enable row level security; alter table public.omegia_events enable row level security; alter table public.omegia_event_rsvps enable row level security;
drop policy if exists "groups read authenticated" on public.omegia_groups; create policy "groups read authenticated" on public.omegia_groups for select to authenticated using(true);
drop policy if exists "groups create self" on public.omegia_groups; create policy "groups create self" on public.omegia_groups for insert to authenticated with check(created_by=(select auth.uid()));
drop policy if exists "groups update owner" on public.omegia_groups; create policy "groups update owner" on public.omegia_groups for update to authenticated using(created_by=(select auth.uid())) with check(created_by=(select auth.uid()));
drop policy if exists "groups delete owner" on public.omegia_groups; create policy "groups delete owner" on public.omegia_groups for delete to authenticated using(created_by=(select auth.uid()));
drop policy if exists "group members read" on public.omegia_group_members; create policy "group members read" on public.omegia_group_members for select to authenticated using(true);
drop policy if exists "group members join self" on public.omegia_group_members; create policy "group members join self" on public.omegia_group_members for insert to authenticated with check(user_id=(select auth.uid()) or exists(select 1 from public.omegia_groups g where g.id=group_id and g.created_by=(select auth.uid())));
drop policy if exists "group members leave self" on public.omegia_group_members; create policy "group members leave self" on public.omegia_group_members for delete to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.omegia_groups g where g.id=group_id and g.created_by=(select auth.uid())));
drop policy if exists "pages read authenticated" on public.omegia_pages; create policy "pages read authenticated" on public.omegia_pages for select to authenticated using(true);
drop policy if exists "pages create self" on public.omegia_pages; create policy "pages create self" on public.omegia_pages for insert to authenticated with check(created_by=(select auth.uid()));
drop policy if exists "pages update owner" on public.omegia_pages; create policy "pages update owner" on public.omegia_pages for update to authenticated using(created_by=(select auth.uid())) with check(created_by=(select auth.uid()));
drop policy if exists "pages delete owner" on public.omegia_pages; create policy "pages delete owner" on public.omegia_pages for delete to authenticated using(created_by=(select auth.uid()));
drop policy if exists "page followers read" on public.omegia_page_followers; create policy "page followers read" on public.omegia_page_followers for select to authenticated using(true);
drop policy if exists "page follow self" on public.omegia_page_followers; create policy "page follow self" on public.omegia_page_followers for insert to authenticated with check(user_id=(select auth.uid()));
drop policy if exists "page unfollow self" on public.omegia_page_followers; create policy "page unfollow self" on public.omegia_page_followers for delete to authenticated using(user_id=(select auth.uid()));
drop policy if exists "events read authenticated" on public.omegia_events; create policy "events read authenticated" on public.omegia_events for select to authenticated using(true);
drop policy if exists "events create self" on public.omegia_events; create policy "events create self" on public.omegia_events for insert to authenticated with check(created_by=(select auth.uid()));
drop policy if exists "events update owner" on public.omegia_events; create policy "events update owner" on public.omegia_events for update to authenticated using(created_by=(select auth.uid())) with check(created_by=(select auth.uid()));
drop policy if exists "events delete owner" on public.omegia_events; create policy "events delete owner" on public.omegia_events for delete to authenticated using(created_by=(select auth.uid()));
drop policy if exists "event rsvps read" on public.omegia_event_rsvps; create policy "event rsvps read" on public.omegia_event_rsvps for select to authenticated using(true);
drop policy if exists "event rsvps insert self" on public.omegia_event_rsvps; create policy "event rsvps insert self" on public.omegia_event_rsvps for insert to authenticated with check(user_id=(select auth.uid()));
drop policy if exists "event rsvps update self" on public.omegia_event_rsvps; create policy "event rsvps update self" on public.omegia_event_rsvps for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
drop policy if exists "event rsvps delete self" on public.omegia_event_rsvps; create policy "event rsvps delete self" on public.omegia_event_rsvps for delete to authenticated using(user_id=(select auth.uid()));
